    {
      "term": {
        "text": "JDK",
        "refs": ["Q0006"]
      },
      "definition_text": {
        "text": "Java Development Kit, a software development environment for building Java applications that includes a compiler, reusable code, a Java Runtime Environment, and other tools.",
        "refs": ["Q0006"]
      },
      "context": null,
      "content": {
        "text": "JDK is short for Java Development Kit and it's basically a software development environment for building Java applications.",
        "refs": ["Q0006"]
      }
    },
    {
      "term": {
        "text": "IDE",
        "refs": ["Q0010"]
      },
      "definition_text": {
        "text": "Integrated Development Environment, a code editor used to write, compile, and run Java programs; examples include IntelliJ IDEA, NetBeans, and Eclipse.",
        "refs": ["Q0010"]
      },
      "context": null,
      "content": {
        "text": "The popular code editors for building Java applications are NetBeans, Eclipse, and IntelliJ.",
        "refs": ["Q0010"]
      }
    },
    {
      "term": {
        "text": "function",
        "refs": ["Q0011"]
      },
      "definition_text": {
        "text": "A block of code that performs a specific task; in Java, functions are defined with a return type, a name, optional parameters, and a body enclosed in curly braces.",
        "refs": ["Q0011", "Q0012", "Q0013", "Q0014"]
      },
      "context": null,
      "content": {
        "text": "The smallest building block in Java programs are functions, which are blocks of code that perform a task.",
        "refs": ["Q0011"]
      }
    },
    {
      "term": {
        "text": "void",
        "refs": ["Q0012"]
      },
      "definition_text": {
        "text": "A reserved keyword in Java indicating that a function does not return a value.",
        "refs": ["Q0012"]
      },
      "context": null,
      "content": {
        "text": "The return type of a function that does not return anything is void.",
        "refs": ["Q0012"]
      }
    }
  ],
  "examples": [],
  "explanations": [
    {
      "topic": {
        "text": "Installing JDK on macOS",
        "refs": ["Q0007", "Q0008", "Q0009"]
      },
      "explanation_text": {
        "text": "Download the JDK DMG file from Oracle's website, open the package, follow the installation wizard by clicking Continue, entering the computer password, and completing the installation.",
        "refs": ["Q0007", "Q0008", "Q0009"]
      },
      "explanation_type": null,
      "content": {
        "text": "The process of downloading and installing the JDK on a Mac involves opening the DMG, running the installer, and moving the installer to trash after completion.",
        "refs": ["Q0007", "Q0008", "Q0009"]
      }
    },
    {
      "topic": {
        "text": "Installing IntelliJ IDEA Community Edition on macOS",
        "refs": ["Q0010"]
      },
      "explanation_text": {
        "text": "Download the IntelliJ IDEA Community Edition from the JetBrains website, drag the application into the Applications folder, and it is ready for use.",
        "refs": ["Q0010"]
      },
      "explanation_type": null,
      "content": {
        "text": "Installation steps for IntelliJ involve downloading, dragging to Applications folder, and confirming installation.",
        "refs": ["Q0010"]
      }
    },
    {
      "topic": {
        "text": "Structure of a Java function",
        "refs": ["Q0012", "Q0013", "Q0014"]
      },
      "explanation_text": {
        "text": "A Java function is declared by specifying a return type, a descriptive name, parentheses for parameters (which may be omitted), and a body enclosed in curly braces containing the executable code.",
        "refs": ["Q0012", "Q0013", "Q0014"]
      },
      "explanation_type": null,
      "content": {
        "text": "Function definition includes return type, name, optional parameters, and code block.",
        "refs": ["Q0012", "Q0013", "Q0014"]
      }
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "The JDK includes a compiler and a Java Runtime Environment.",
        "refs": ["Q0006"]
      },
