        "text": "Install JDK on macOS",
        "refs": ["Q0007", "Q0008", "Q0009"]
      },
      "steps": [
        {
          "text": "Open a web browser and search for \"JDK download\".",
          "refs": ["Q0006"]
        },
        {
          "text": "Navigate to the Oracle Java SE download page and select the appropriate platform (e.g., macOS).",
          "refs": ["Q0007"]
        },
        {
          "text": "Download the DMG file for macOS.",
          "refs": ["Q0008"]
        },
        {
          "text": "Open the downloaded DMG and double‑click the package to launch the installation wizard.",
          "refs": ["Q0009"]
        },
        {
          "text": "Click Continue, accept the license agreement, enter the computer password when prompted, and complete the installation.",
          "refs": ["Q0009"]
        },
        {
          "text": "Move the installer to the trash after installation.",
          "refs": ["Q0009"]
        }
